INSERT OR REPLACE INTO anime (
      id, slug, title, original_title, year, episodes, status,
      personal_rating, poster, backdrop, added_date, last_updated,
      honesty_status, filler_percentage, trending, synopsis,
      franchise_id, franchise_step_order,
      review_heading, review_paragraphs,
      source_title, source_original_title, source_author, source_type,
      source_volumes, source_publication_status, source_adaptation_status,
      source_coverage, source_notes,
      power_system_name, power_system_paragraphs,
      lesson_heading, lesson_takeaway
    ) VALUES (
      'naruto-shippuden', 'naruto-shippuden', 'Naruto Shippuden', 'NARUTO -ナルト- 疾風伝', 2007, 500, 'Finished Airing',
      9, 'https://image.tmdb.org/t/p/w780/kV27gZqdaUQmFO3m6rEcvEpWzZN.jpg', 'https://image.tmdb.org/t/p/w1280/vIjyK706i8qfU3556gVvJ8Z8V6X.jpg', 'Jan 10, 2024', 'Nov 02, 2024',
      'watched', 41, 1, 'Naruto returns to the Hidden Leaf village after two and a half years of rigorous training with Jiraiya, facing the emerging threat of the shadowy Akatsuki syndicate seeking the Nine-Tailed Fox.',
      'naruto', 2,
      'A Generational Epic That Truly Demands a Filler Guide', '["If you cut out the 41% filler bloat, Naruto Shippuden is one of the most emotionally devastating and rewarding fantasy stories ever told. When it hits, nothing else in battle shonen comes close — the fight between Kakashi and Obito in the Kamui dimension is still peak anime choreography, and the emotional payoff of Naruto confronting Pain after the village destruction genuinely made me tear up.","That being said, the pacing in the final war arc can test your patience even when you skip the filler episodes, with constant flashback repetitions mid-fight. But the core story, Yasuharu Takanashi’s unforgettable soundtrack, and the ideological clashes make it an absolute triumph that I find myself rewatching every few years."]',
      'Naruto', 'NARUTO -ナルト-', 'Masashi Kishimoto', 'Manga',
      '72 Volumes / 700 Chapters', 'Completed (1999 – 2014)', 'Fully Adapted',
      'Anime adapts Chapters 245 through 700. The original pre-Shippuden series adapted Chapters 1 to 244.', 'Light novel epilogues (Kakashi Hiden, Shikamaru Hiden, Sasuke Shinden) were adapted into episodes 484–500.',
      'Chakra & Ninjutsu System', '["The power system of Naruto is grounded in Chakra — a mystical energy generated by blending physical energy gathered from every cell in the body with spiritual energy gained through study and experience. Once shaped through hand seals, chakra can be manifested into Ninjutsu (elemental attacks), Genjutsu (illusions targeting the nervous system), or Taijutsu (enhanced martial arts).","Advanced practitioners manifest Nature Transformations across five basic elements: Fire, Wind, Lightning, Earth, and Water. The rare fusion of two distinct natures simultaneously gives birth to Kekkei Genkai (bloodline traits such as Ice or Wood Release), while Kekkei Tota combines three elements into devastating Particle Style.","Beyond human chakra lies Senjutsu — drawing natural energy from the surrounding world into the body to enter Sage Mode. The ultimate tier involves Six Paths Chakra and the power of the Tailed Beasts, which grant nearly limitless reality-warping endurance."]',
      'Empathy & Consistent Dedication', 'True strength is not the ability to overpower enemies, but the endurance to understand why they are hurting. Talent is cheap compared to consistent, daily dedication.'
    );
