INSERT INTO franchise_watch_order (franchise_id, step_order, title, type, episodes, anime_id, note) VALUES ('frieren', 1, 'Frieren: Beyond Journey''s End (Season 1)', 'TV Series', '28 Episodes', 'frieren', 'Complete Season 1 covering chapters 1 to 60.');
INSERT OR REPLACE INTO anime (
      id, slug, title, original_title, year, episodes, status,
      personal_rating, poster, backdrop, added_date, last_updated,
      honesty_status, filler_percentage, trending, synopsis,
      franchise_id, franchise_step_order,
      review_heading, review_paragraphs,
      source_title, source_original_title, source_author, source_type,
      source_volumes, source_publication_status, source_adaptation_status,
      source_coverage, source_notes,
      power_system_name, power_system_paragraphs,
      lesson_heading, lesson_takeaway
    ) VALUES (
      'frieren', 'frieren-beyond-journeys-end', 'Frieren: Beyond Journey''s End', '葬送のフリーレン (Sousou no Frieren)', 2023, 28, 'Finished Airing',
      9.8, 'https://image.tmdb.org/t/p/w780/dqZENchTd7lp5zht7BdlqM7RBhD.jpg', 'https://image.tmdb.org/t/p/w1280/5MAq48e77aP78s2C3sZl8Xm3J8d.jpg', 'Jan 15, 2024', 'Oct 20, 2024',
      'watched', 0, 1, 'An immortal elf mage and her human companions defeat the Demon King. But after 50 years pass and her former friends begin to pass away, she embarks on a quiet journey to understand the brevity of human life.',
      'frieren', 1,
      'The Rare Anime That Transcends Its Medium', '["Frieren is easily one of the greatest anime I have ever seen. What makes it so special isn’t just the jaw-dropping animation by Madhouse or Evan Call’s majestic orchestral score — it is the quiet, patient maturity in how it approaches grief, memory, and ordinary everyday moments.","It takes a few episodes to settle into its relaxed rhythm, so if you go in expecting non-stop shonen tournament battles, the deliberate pacing might catch you off guard at first. But once the world opens up, every single interaction carries genuine weight. The magic exam arc in the second half manages to be tactically exhilarating while preserving the introspective soul of the story."]',
      'Frieren: Beyond Journey''s End', '葬送のフリーレン', 'Kanehito Yamada (Story), Tsukasa Abe (Art)', 'Manga',
      '13+ Volumes (Ongoing)', 'Ongoing', 'Ongoing Adaptation',
      'Season 1 adapts Chapters 1 through 60 (up to the conclusion of the First-Class Mage Exam).', 'To continue where the anime left off, start reading at Chapter 61 (Volume 7).',
      'Mana Visualization & Classical Spellcraft', '["Magic in Frieren operates on visualization: a mage cannot manifest a spell unless they can clearly and concretely picture it in their mind. What cannot be visualized is strictly impossible.","Mana control is vital. Skilled mages suppress their leaking mana to fool demon predators into underestimating their lethal range. Combat spells are fast, direct, and lethal, where a single second of distraction results in defeat.","Folk magic (cleaning clothes, turning sweet grapes sour) exists alongside combat spells, representing the everyday beauty of living in a peaceful world."]',
      'The Precious Value of Ordinary Time', 'We live as if we have an infinite supply of tomorrows. Kindness, shared memories, and small everyday moments are the only things that truly survive us.'
    );
