INSERT INTO franchise_watch_order (franchise_id, step_order, title, type, episodes, anime_id, note) VALUES ('jujutsu-kaisen', 3, 'Jujutsu Kaisen Season 2 (Hidden Inventory & Shibuya Incident)', 'TV Series', '23 Episodes', 'jujutsu-kaisen', 'Gojo’s past followed by the catastrophic Shibuya Incident.');
INSERT OR REPLACE INTO anime (
      id, slug, title, original_title, year, episodes, status,
      personal_rating, poster, backdrop, added_date, last_updated,
      honesty_status, filler_percentage, trending, synopsis,
      franchise_id, franchise_step_order,
      review_heading, review_paragraphs,
      source_title, source_original_title, source_author, source_type,
      source_volumes, source_publication_status, source_adaptation_status,
      source_coverage, source_notes,
      power_system_name, power_system_paragraphs,
      lesson_heading, lesson_takeaway
    ) VALUES (
      'jujutsu-kaisen', 'jujutsu-kaisen', 'Jujutsu Kaisen', '呪術廻戦', 2020, 47, 'Ongoing',
      9.2, 'https://image.tmdb.org/t/p/w780/hFWP5HkbVEe40hrXgtCe5xUCvM7.jpg', 'https://image.tmdb.org/t/p/w1280/kXfqcdQKsToO0OUXHcrrNCHDBzO.jpg', 'Jan 18, 2024', 'Nov 01, 2024',
      'watched', 0, 1, 'A high schooler with astonishing physical prowess swallows a cursed talisman to save a friend, becoming host to the Legendary King of Curses Ryomen Sukuna.',
      'jujutsu-kaisen', 3,
      'Pure Kinetic Adrenaline with Unforgiving Stakes', '["MAPPA went completely feral on the animation in Season 2. The Shibuya Incident is a non-stop gauntlet where every episode feels like a season finale, and the series is completely unafraid to kill off beloved characters or put them through absolute psychological misery.","My only real critique is that the pacing is so relentless that there is almost zero downtime for quiet character banter once the action kicks off. But as far as raw sakuga combat, inventive power systems, and high emotional stakes go, it is modern battle shonen operating at the absolute highest level."]',
      'Jujutsu Kaisen', '呪術廻戦', 'Gege Akutami', 'Manga',
      '28+ Volumes (Completed in Manga)', 'Completed (2018 – 2024)', 'Ongoing Adaptation',
      'Season 2 finishes at Chapter 137. The manga concludes at Chapter 271.', 'To continue after Shibuya, start reading at Chapter 138 (Culling Game Arc).',
      'Cursed Energy & Domain Expansion', '["Cursed Energy leaks from the negative emotions of humans. Sorcerers channel this raw energy into refined Cursed Techniques imprinted into their bodies from birth.","The pinnacle of jujutsu is Domain Expansion: creating a separate metaphysical space imbued with the user’s innate technique where all attacks are guaranteed to hit.","Binding Vows allow sorcerers to artificially create self-imposed restrictions (such as explaining their technique to the opponent) in exchange for exponential increases in output."]',
      NULL, NULL
    );
