INSERT OR REPLACE INTO anime (
      id, slug, title, original_title, year, episodes, status,
      personal_rating, poster, backdrop, added_date, last_updated,
      honesty_status, filler_percentage, trending, synopsis,
      franchise_id, franchise_step_order,
      review_heading, review_paragraphs,
      source_title, source_original_title, source_author, source_type,
      source_volumes, source_publication_status, source_adaptation_status,
      source_coverage, source_notes,
      power_system_name, power_system_paragraphs,
      lesson_heading, lesson_takeaway
    ) VALUES (
      'solo-leveling', 'solo-leveling', 'Solo Leveling', '나 혼자만 레벨업 (Ore dake Level Up na Ken)', 2024, 25, 'Ongoing',
      8.8, 'https://image.tmdb.org/t/p/w780/geCRueV3ElhRTr0xtJuPxJ8HGQH.jpg', 'https://image.tmdb.org/t/p/w1280/2rmK7mnchsl935x82Rp8ea7LZkd.jpg', 'Jan 25, 2024', 'Nov 04, 2024',
      'watched', 0, 1, 'Known as the weakest hunter of all mankind, Sung Jinwoo is trapped in a deadly double dungeon. Surviving against all odds, a mysterious quest log grants him the ability to level up infinitely.',
      'solo-leveling', 3,
      'The Gold Standard of Power Fantasy Dopamine', '["Solo Leveling does not pretend to be a deep philosophical meditation — it is pure, unadulterated power fantasy progression, and it executes that formula better than almost anything else. Sung Jinwoo’s rise from bottom-tier fodder to commanding legions of shadow soldiers is accompanied by Hiroyuki Sawano’s pulse-pounding soundtrack.","The supporting cast definitely takes a back seat as Jinwoo scales up, but if you want crisp fight animation, crunchy impact sounds, and pure hype payoffs, this delivers in spades."]',
      'Solo Leveling (Only I Level Up)', '나 혼자만 level up', 'Chugong (Novel), DUBU/REDICE (Webtoon Art)', 'Webtoon / Manhwa',
      '179 Chapters (Completed)', 'Completed (2018 – 2021)', 'Ongoing Adaptation',
      'Season 1 covers webtoon Chapters 1 to 45.', 'Webtoon is fully completed and available in full-color format.',
      'Hunter Awakening & The System', '["In the world of Solo Leveling, humans undergo an \"Awakening\" that grants them fixed magical ranks from E to S. Ranks are strictly permanent and cannot be increased through training.","Sung Jinwoo is the sole exception: the \"System\" turns his reality into an RPG interface with daily quests, stat points, inventory storage, and skill trees.","His primary class ability, Shadow Extraction, extracts souls from fallen enemies to forge an immortal army of loyal shadows."]',
      NULL, NULL
    );
