INSERT OR REPLACE INTO anime (
      id, slug, title, original_title, year, episodes, status,
      personal_rating, poster, backdrop, added_date, last_updated,
      honesty_status, filler_percentage, trending, synopsis,
      franchise_id, franchise_step_order,
      review_heading, review_paragraphs,
      source_title, source_original_title, source_author, source_type,
      source_volumes, source_publication_status, source_adaptation_status,
      source_coverage, source_notes,
      power_system_name, power_system_paragraphs,
      lesson_heading, lesson_takeaway
    ) VALUES (
      'mob-psycho-100', 'mob-psycho-100', 'Mob Psycho 100', 'モブサイコ100', 2016, 37, 'Finished Airing',
      9.7, 'https://image.tmdb.org/t/p/w780/29A2n2M8G6xY5y1Q3rG0sK7w8p9.jpg', 'https://image.tmdb.org/t/p/w1280/3wY8M2V8kQ9y7wW6uY4pZ1yK0m5.jpg', 'Jan 05, 2024', 'Aug 25, 2024',
      'watched', 0, 0, 'An eighth-grader with godlike psychic abilities suppresses his emotions to prevent psychic explosions, seeking only to improve his physical fitness to impress his middle-school crush.',
      'mob-psycho-100', 3,
      'One of the Rare Complete, Flawless Three-Season Runs', '["Mob Psycho 100 has everything: mind-bending sakuga animation from Studio BONES, genuine belly-laugh humor, and arguably the most wholesome emotional core in all of anime. Reigen Arataka could have easily been an annoying gimmick character, but he turns out to be one of the best mentors ever written.","All three seasons tell a complete, tightly paced story with zero wasted episodes, ending on the rare, coveted perfect series finale."]',
      'Mob Psycho 100', 'モブサイコ100', 'ONE', 'Manga',
      '16 Volumes / 101 Chapters', 'Completed (2012 – 2017)', 'Fully Adapted',
      'The anime adapts the entire manga from Chapter 1 to 101 with complete closure.', 'No manga reading required after finishing Season 3.',
      'Esper Telekinesis & Emotional Threshold (100%)', '["Psychic power in Mob Psycho 100 is fueled by suppressed human emotions: Anger, Sadness, Gratitude, and Courage.","When Mob reaches 100% emotional intensity, his psychic seal bursts, unleashing city-level telekinetic storms. If knocked unconscious, his subconscious \"???%\" mode emerges with cataclysmic scale."]',
      'Humility & Working on What’s Difficult', 'Having a special talent doesn’t make you better than anyone else. True self-esteem comes from working hard on the things that are genuinely difficult for you.'
    );
