      'bleach-tybw', 'bleach-thousand-year-blood-war', 'Bleach: Thousand-Year Blood War', 'BLEACH 千年血戦篇', 2022, 39, 'Ongoing',
      NULL, 'https://image.tmdb.org/t/p/w780/b5rX1b9dC1E8OQ102F3J2lT2YtN.jpg', 'https://image.tmdb.org/t/p/w1280/vIjyK706i8qfU3556gVvJ8Z8V6X.jpg', 'Jan 28, 2024', 'Nov 02, 2024',
      'watchlist', 0, 1, 'Peace is shattered when an alarm sounds through the Soul Society. The Quincy King Yhwach emerges from the shadows to wage total war against the Soul Reapers.',
      'bleach', 3,
      NULL, NULL,
